const collectionAnswers = require('./lib/collectAnswers')

const questions = [
    "What's your name?",
    "Where do you live?",
    "What are you going to do with Node.js?"
]


const answersEvents = collectionAnswers(questions, (answers) => {
    console.log('Thanks for answering!')
    console.log(answers)
    process.exit()
})

answersEvents.on('answer', (answer) => {
    console.log(`The answer is ${answer}`)
})